ALTER TABLE "gate_chat_turns" ADD CONSTRAINT "gate_chat_turns_terminal_state_check" CHECK (("gate_chat_turns"."state" = 'pending' and "gate_chat_turns"."agent_message_id" is null) or ("gate_chat_turns"."state" = 'completed' and "gate_chat_turns"."agent_message_id" is not null and "gate_chat_turns"."completed_at" is not null and "gate_chat_turns"."error_code" is null) or ("gate_chat_turns"."state" in ('failed', 'aborted') and "gate_chat_turns"."agent_message_id" is null and "gate_chat_turns"."completed_at" is not null and "gate_chat_turns"."error_code" is not null));